(()=>{const app=document.querySelector('#app'),modal=document.querySelector('#modal'),body=document.querySelector('#modal-body'),title=document.querySelector('#modal-title');const mock='<span class="mock">● 演示数据 / Mock Data</span>';const facts='<table><thead><tr><th>事实</th><th>数值</th><th>期间/单位</th><th>来源</th></tr></thead><tbody><tr><td>Revenue</td><td>$130.5B</td><td>FY2025 · USD</td><td><button data-source="SEC 10-K">SEC 10-K · 模拟定位</button></td></tr><tr><td>Net income</td><td>$72.9B</td><td>FY2025 · USD</td><td><button data-source="SEC Company Facts">Company Facts · 模拟定位</button></td></tr></tbody></table>';function layout(x){app.innerHTML='<div class="wrap">'+x+'</div>'}function home(){layout('<section class="hero"><div class="panel"><span class="tag">P0 原型闭环</span><h1>把行情与 SEC 证据放在同一条研究路径里</h1><p class="muted">搜索股票，查看已保存日线、财务事实、来源和数据状态。'+mock+'</p><div class="search"><input id="query" value="NVDA" aria-label="股票代码或公司名称"><button class="primary" id="analyze">开始分析</button></div><p class="small muted">演示选项：NVDA · AAPL · MSFT。当前不连接 API，不提供投资建议。</p></div><div class="panel"><h2>最近分析</h2><div class="status ok">NVDA · 研究快照 <span class="mock">Mock</span><br><span class="small muted">日线已保存 · SEC 文件可查看</span></div><div class="status warn">新闻时间线：接口预留<br><span class="small muted">尚未接入真实新闻数据</span></div></div></section><div class="section-title"><h2>本轮验证重点</h2><span class="muted">证据优先，Agent 过程隐藏</span></div><div class="grid"><div class="card"><b>已保存日线</b><p class="muted">查看 OHLCV、日期、来源和延迟状态。</p></div><div class="card"><b>可追溯事实</b><p class="muted">每个数字展示单位、期间和文件来源。</p></div><div class="card"><b>可展开证据</b><p class="muted">先读摘要，再查看事实与风险限制。</p></div></div>');document.querySelector('#analyze').onclick=()=>process(document.querySelector('#query').value.trim()||'NVDA')}function process(s){layout('<div class="panel"><span class="tag">分析流程</span><h1>'+s+' 数据准备</h1><p class="muted">'+mock+' 离线演示步骤，不代表真实请求。</p>'+['读取已保存行情','获取 SEC 文件','提取财务事实','检查时间和来源','生成摘要','准备导出'].map(x=>'<div class="status ok">✓ '+x+'</div>').join('')+'<div class="actions"><button class="primary" id="report">查看演示报告</button><button data-view="home">返回搜索</button></div></div>');document.querySelector('#report').onclick=report}function report(){layout('<div class="section-title"><div><span class="tag">NVDA · 单股研究</span><h1>研究快照与证据摘要</h1></div><span class="mock">Mock Data</span></div><div class="notice">数据状态：日线为已保存演示快照；行情截止 2026-09-18，允许 5–15 分钟延迟。SEC 事实为模拟展示，真实 RAG 尚未实现。</div><div class="two"><div class="card"><h2>股票基本信息</h2><p><b>NVIDIA Corporation</b> · NASDAQ · NVDA</p><p class="muted">来源：本地保存快照｜数据截止：2026-09-18 16:00 ET｜币种：USD</p><h2>日线行情概览</h2><div class="grid"><div><span class="muted">收盘价</span><div class="metric">$178.24</div></div><div><span class="muted">当日涨跌</span><div class="metric">+1.8%</div></div><div><span class="muted">成交量</span><div class="metric">42.1M</div></div></div><p class="small muted">复权：未复权；来源状态：保存快照；数值均为 Mock Data。</p><h2>简化 K 线预览</h2><div class="chart" aria-label="NVDA演示K线图"><svg viewBox="0 0 600 190" role="img"><polyline points="10,145 80,120 150,132 220,90 290,110 360,65 430,84 500,40 590,58" fill="none" stroke="#53d6b2" stroke-width="4"/><g stroke="#91a0b5" stroke-width="2"><line x1="80" y1="108" x2="80" y2="142"/><line x1="220" y1="75" x2="220" y2="108"/><line x1="360" y1="48" x2="360" y2="82"/><line x1="500" y1="24" x2="500" y2="57"/></g></svg></div><p class="small mock">固定 synthetic 日K示意，不是真实 NVDA 行情；日期、OHLC、成交量仅用于交互演示。</p></div><div class="card"><h2>简短摘要</h2><p><b>事实：</b>演示快照显示收入与净利润均有记录。</p><p><b>计算：</b>收盘价和涨跌幅来自已保存日线字段。</p><p><b>推断：</b>仅提供需要进一步核验的研究线索。</p><p><b>风险与缺失：</b>新闻未接入，不能完成事件归因；K线为 Mock Data。</p><button class="primary" id="evidence">展开证据</button><h2>SEC 文件与财务事实</h2>'+facts+'<div class="actions"><button id="excel">预览 Excel 导出</button><button id="runlog">查看运行记录</button><button>加入自选股（后续功能）</button></div><p class="small muted">报告已生成 ≠ 邮件已发送。邮件属于 P1，当前默认关闭。</p></div></div>');document.querySelector('#evidence').onclick=()=>openModal('证据详情','<p><b>事实</b>：财务数字来自模拟 SEC 文件卡片。</p><p><b>计算</b>：涨跌幅由保存的开收盘字段确定性计算。</p><p><b>推断</b>：不能替代投资判断。</p><p><b>风险</b>：新闻、完整 RAG 和多 Agent 尚未实现；缺失数据不会填 0。</p>');document.querySelector('#excel').onclick=excel;document.querySelector('#runlog').onclick=runlog;document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>openModal('来源卡片','<p><b>'+b.dataset.source+'</b></p><p>官方来源位置和公开时间将在真实数据接入后保存。当前为 Mock Data，不能打开真实文件。</p>'))}function excel(){openModal('Excel 导出预览','<p class="mock">Mock Data · 当前不会真正下载文件</p><p>真实导出只能读取已保存快照，数字不能由 LLM 临时生成。</p><ul>'+['Summary','Daily OHLCV','SEC Facts','Sources','Data Quality','Run Log'].map(x=>'<li>'+x+'</li>').join('')+'</ul><p class="muted">每个工作表将保存来源、时间、单位、口径、延迟和缺失状态。</p>')}function runlog(){openModal('运行记录（原型模拟）','<table><tbody>'+[['run_id','demo-run-nvda-001'],['symbol','NVDA'],['started_at','2026-09-18T20:00:00Z'],['completed_at','2026-09-18T20:00:03Z'],['data_as_of','2026-09-18T20:00:00Z'],['market_source','saved daily snapshot (Mock)'],['SEC source','SEC fixture (Mock)'],['task_status','completed (prototype)'],['missing_data','news timeline'],['warnings','not investment advice; RAG not implemented'],['export_status','preview only; not downloaded']].map(x=>'<tr><th>'+x[0]+'</th><td>'+x[1]+'</td></tr>').join('')+'</tbody></table>')}function openModal(t,c){title.textContent=t;body.innerHTML=c;modal.classList.add('open');modal.setAttribute('aria-hidden','false');modal.querySelector('.close').focus()}function closeModal(){modal.classList.remove('open');modal.setAttribute('aria-hidden','true')}function secondary(v){layout('<div class="panel"><span class="tag">后续功能</span><h1>'+({watchlist:'自选股',daily:'收盘报告',history:'历史复盘'}[v]||'后续功能')+'</h1><p class="muted">该页面保留用于范围展示，当前不抢占 P0 验证路径。</p><div class="notice">待实现：分钟级监测、邮件投递、5/20 交易日复盘和真实数据连接。</div><button data-view="home">回到 NVDA 搜索</button></div>')}document.addEventListener('click',e=>{const v=e.target.dataset.view;if(v){v==='home'?home():secondary(v)}});modal.querySelector('.close').onclick=closeModal;modal.addEventListener('click',e=>{if(e.target===modal)closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('open'))closeModal()});home()})();
